 TitleBlockCell cell;cell.cell_type=TitleBlockCell::TextCell;cell.label_style=style;cell.value_style=style;QUndoStack stack;auto *batch=new QUndoCommand("Bulk test");auto *change=new ModifyTitleBlockCellCommand(&cell,batch);change->addModification("label_style",merged);stack.push(batch);check(cell.label_style==merged&&cell.value_style==style,"caption-only formatting preserves value");stack.undo();check(cell.label_style==style,"bulk formatting Undo");stack.redo();QDomDocument doc;auto xml=doc.createElement("cell");cell.saveContentToXml(xml);TitleBlockCell loaded;loaded.loadContentFromXml(xml);check(loaded.label_style==merged,"title-block style XML roundtrip");stack.clear();

 // Exercise real bulk dialog with selected cells, then all cells, and cancellation.
